WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT t.id, t.prefixo, t.criado_em, t.ultimo_uso, t.revogado_em, e.id AS executivo_id, e.nome AS usuario FROM tokens_api t JOIN eu ON eu.admin JOIN executivos e ON e.id = t.executivo_id ORDER BY (t.revogado_em IS NOT NULL), t.id DESC LIMIT 200
